INSERT INTO articulos (
  slug, titulo, extracto, contenido, imagen_destacada, estado, metadata, created_at, updated_at, categoria_id, autor_id
) VALUES (
  'el-guardian-de-las-llaves', 'El Guardián de las Llaves', 'Dinámica de sensibilidad táctil y concentración a ciegas donde el participante busca la llave correcta de un candado bajo tiempo.', '<h2>📜 Descripción de El Guardián de las Llaves</h2>
<p><b>El Guardián de las Llaves</b> es una dinámica de percepción táctil, control del estrés y atención enfocada a ciegas. Se selecciona a un participante para asumir el rol de <i>''El Guardián''</i>, a quien se le colocan vendajes en los ojos antes de entregarle un abultado manojo de llaves metálicas de distintas formas y tamaños.</p>
<p>Frente al Guardián se ubica una cerradura de puerta o un candado de caja misteriosa. Con la unidad en absoluto silencio para mantener el clima de suspenso, el jugador debe palpar las ranuras de la cerradura, examinar táctilmente las llaves del manojo e identificar cuál es la única llave exacta que calza en el cerrojo, cronometrándose el tiempo empleado en abrirla.</p>
<p>Esta actividad ejercita la motricidad fina sin mirar, la concentración bajo presión, el sentido del tacto y el respeto al silencio colectivo en Manada, Compañía, Tropa, Avanzada y Clan.</p>

<h2>🎲 ¿Cómo se juega El Guardián de las Llaves?</h2>
<p>Para llevar a cabo la dinámica con misterio, paciencia y concentración, los dirigentes deben seguir estos pasos:</p>
<ul>
  <li><b>Preparación del Guardián:</b> Se vendan los ojos del participante designado y se le sitúa frente al candado.</li>
  <li><b>Entrega del Manojo:</b> Se le entrega en las manos el conjunto de llaves mezcladas.</li>
  <li><b>Silencio de Suspenso:</b> Toda la unidad permanece en absoluto silencio mientras corre el cronómetro.</li>
  <li><b>Exploración Táctil:</b> El Guardián palpa los dientes y surcos de las llaves probándolas en la cerradura a ciegas.</li>
  <li><b>Apertura y Registro:</b> Se detiene el cronómetro en el instante exacto en que gira el cerrojo y se abren los aplausos.</li>
</ul>

<h2>🏆 Cómputo de Puntos y Condición de Victoria de El Guardián de las Llaves</h2>
<p>La actividad valora la agudeza táctil y el autocontrol en el Tally:</p>
<ul>
  <li><b>Mejor Tiempo de Apertura:</b> Otorgar 5 puntos al participante o patrulla que logre abrir el candado en menos segundos.</li>
  <li><b>Concentración e Inmunidad al Estrés:</b> Otorgar 3 puntos al jugador que mantenga la calma sin soltar el manojo.</li>
  <li><b>Silencio Respetuoso del Grupo:</b> Otorgar 3 puntos al equipo que guarde el mayor silencio durante la prueba.</li>
</ul>', '/uploads/el-guardian-de-las-llaves.webp', 'publicado', '{"areas": ["creatividad", "sociabilidad"], "unidades": ["manada", "compañía", "tropa", "avanzada", "clan"], "duracion": "15 minutos", "cantidad": "02 participantes", "lugares": ["Interior", "Salón", "Sala"], "materiales": ["Manojo de Llaves", "Venda para Ojos", "Cronómetro"], "objetivos": ["Reforzar el desarrollo de los sentidos", "Estimular la agilidad mental", "Reforzar el poner atención", "Trabajo en equipo"], "justificacion_areas": "El Guardián de las Llaves potencia la creatividad al exigir la construcción de imágenes mentales tridimensionales basadas únicamente en la percepción táctil. Desarrolla la sociabilidad al afianzar el respeto al silencio colectivo y la empatía en la superación de desafíos individuales ante la unidad.", "variaciones": "<b>Guardián con Llave Falsa (Broma Fina):</b> Para el último participante, se retira la llave correcta del manojo durante 30 segundos de humor.<br><b>El Guardián en Silencio Absoluto:</b> Si el Guardián emite un ruido o el grupo habla, se añaden 5 segundos de penalización.<br><b>Relevos de Llaves en Pareja:</b> Dos participantes vendados se dividen el manojo probando llaves alternadamente.", "recomendaciones": "Utilizar cerraduras y candados seguros sin bordes filosos. Mantener una atmósfera de suspenso respetuoso.", "objetivos_educativos": [{"id": "a2ef0709-ac6d-4d90-9fe8-c96eeff5cf14", "area": "Creatividad", "unidad": "Manada", "texto": "Actúa con agilidad mental ante las situaciones más diversas, desarrollando su capacidad de pensar, innovar y aventurar.", "como_se_cumple": "Tocando los dientecitos de cada llave metálica con la yema de mis dedos para adivinar cuál es la correcta sin mirar."}, {"id": "b69188bf-2391-43c1-a885-abd1b13912be", "area": "Sociabilidad", "unidad": "Manada", "texto": "Acepto las reglas que se ponen en mi casa, en la escuela y en la Manada.", "como_se_cumple": "Haciendo silencio respetuoso con mi seisena mientras el compañero busca la llave para no distraerlo."}, {"id": "418f2b77-f15b-405a-95bd-8033c0b6a4c2", "area": "Creatividad", "unidad": "Manada", "texto": "Actúa con agilidad mental ante las situaciones más diversas, desarrollando su capacidad de pensar, innovar y aventurar.", "como_se_cumple": "Concentrándome con paciencia en el tacto de mis manos para encontrar la llave que abre el candado."}, {"id": "2394dd5b-87b9-4f3d-9cdd-a42649139782", "area": "Sociabilidad", "unidad": "Manada", "texto": "Comprendo y respeto las normas que se han puesto en mi casa y en la escuela, aunque no siempre esté de acuerdo con ellas", "como_se_cumple": "Esperando con paciencia y alegría mi turno con los ojos vendados para probar mi agilidad táctil."}, {"id": "11320fb6-98de-4725-825d-db858e3bffa2", "area": "Creatividad", "unidad": "Compañía", "texto": "Perfecciono mis habilidades manuales.", "como_se_cumple": "Desarrollando la sensibilidad fina de las manos para identificar los surcos y forma de las llaves a ciegas."}, {"id": "007e85ea-2b06-48c2-8ac1-873d59643aae", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Guardando un silencio riguroso durante la prueba para favorecer la concentración de la compañera en turno."}, {"id": "4e6b0cd4-85bb-404b-9af2-36fd5b2a4f04", "area": "Creatividad", "unidad": "Compañía", "texto": "Actúa con agilidad mental ante las situaciones más diversas, desarrollando su capacidad de pensar, innovar y aventurar.", "como_se_cumple": "Resolviendo el desafío táctil bajo presión de tiempo con serenidad y agudeza en el tacto de las manos."}, {"id": "de2f5693-de4b-48f1-b870-3c62be99aea8", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Apoyando con aplausos fraternos el esfuerzo de cada integrante al abrir la puerta."}, {"id": "103661fc-3396-4eac-9182-58b7e54d5115", "area": "Creatividad", "unidad": "Tropa", "texto": "Perfecciono mis habilidades manuales.", "como_se_cumple": "Desarrollando la sensibilidad fina de las manos para identificar los surcos y forma de las llaves a ciegas."}, {"id": "857f21bc-db3c-4e5e-bcd5-d3d331276fad", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Guardando un silencio riguroso durante la prueba para favorecer la concentración del compañero en turno."}, {"id": "9fe305a1-531d-47b6-9aaa-e7d6b2dbd3b1", "area": "Creatividad", "unidad": "Tropa", "texto": "Actúa con agilidad mental ante las situaciones más diversas, desarrollando su capacidad de pensar, innovar y aventurar.", "como_se_cumple": "Resolviendo el desafío táctil bajo presión de tiempo con serenidad y agudeza en el tacto de las manos."}, {"id": "bbc48d53-f4aa-4de7-84d4-95614df76034", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Apoyando con aplausos fraternos el esfuerzo de cada integrante al abrir la puerta."}, {"id": "fe57c89e-be7b-46a1-b370-64df400355fa", "area": "Creatividad", "unidad": "Avanzada", "texto": "Trato de aprender más sobre cuestiones técnicas relacionadas con el sonido, la imagen, la mecánica, la informática y otros.", "como_se_cumple": "Desarrollando el autocontrol sensorial y la concentración táctil bajo presión."}, {"id": "7e7417a5-a16e-4ff3-843f-93e711d017d4", "area": "Sociabilidad", "unidad": "Avanzada", "texto": "Contribuyo a preservar la vida a través de la conservación de la integridad del mundo natural.", "como_se_cumple": "Fomentando el respeto y la empatía en retos de superación individual en Avanzada."}, {"id": "29eee8b1-a414-4df9-90e1-520a384fb9aa", "area": "Creatividad", "unidad": "Clan", "texto": "Uno los conocimientos teórico y práctico mediante la aplicación constante de mis habilidades técnicas y manuales.", "como_se_cumple": "Aplicando destrezas de percepción táctil y paciencia en la resolución de problemas con los ojos vendados."}, {"id": "c4f78e61-6790-4cf4-b477-993900b5bf02", "area": "Sociabilidad", "unidad": "Clan", "texto": "Contribuyo a preservar la vida a través de la conservación de la integridad del mundo natural.", "como_se_cumple": "Promoviendo el silencio y la disciplina contemplativa en el Clan Rover."}]}'::jsonb, NOW(), NOW(), NULL, NULL
